CREATE TABLE leo_work_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),child_id uuid,kind text NOT NULL CHECK(kind IN ('care-summary-draft','crm-followup')),payload jsonb NOT NULL,source_ids uuid[] NOT NULL,source_hash text NOT NULL,state text NOT NULL DEFAULT 'proposed' CHECK(state IN ('proposed','drafted','approved','executed','cancelled')),draft_text text,created_by uuid NOT NULL,approved_by uuid,approved_at timestamptz,output_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id));
CREATE INDEX leo_work_items_scope ON leo_work_items(organization_id,created_at DESC);
ALTER TABLE leo_work_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY leo_tasks_read ON leo_work_items FOR SELECT TO daylio_app USING(organization_id=app_org() AND app_has_feature('leo') AND ((app_role() IN ('owner','manager') AND (kind<>'crm-followup' OR app_capability('crm'))) OR (app_role()='caregiver' AND created_by=app_user() AND child_id IS NOT NULL AND can_child(child_id))));
CREATE POLICY leo_tasks_create ON leo_work_items FOR INSERT TO daylio_app WITH CHECK(organization_id=app_org() AND app_has_feature('leo') AND created_by=app_user() AND state='proposed' AND ((app_role() IN ('owner','manager') AND (kind<>'crm-followup' OR app_capability('crm'))) OR (app_role()='caregiver' AND kind='care-summary-draft' AND child_id IS NOT NULL AND can_child(child_id))));
CREATE POLICY leo_tasks_update ON leo_work_items FOR UPDATE TO daylio_app USING(organization_id=app_org() AND app_has_feature('leo') AND ((app_role() IN ('owner','manager') AND (kind<>'crm-followup' OR app_capability('crm'))) OR (app_role()='caregiver' AND created_by=app_user() AND child_id IS NOT NULL AND can_child(child_id)))) WITH CHECK(organization_id=app_org() AND app_has_feature('leo') AND ((app_role() IN ('owner','manager') AND (kind<>'crm-followup' OR app_capability('crm'))) OR (app_role()='caregiver' AND created_by=app_user() AND child_id IS NOT NULL AND can_child(child_id) AND state IN ('proposed','drafted','cancelled'))));
GRANT SELECT,INSERT,UPDATE ON leo_work_items TO daylio_app;
